import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public class RevenueLeaderboardTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final List<String> SALES = Arrays.asList(
            "north,widget,120",
            "north,gizmo,200",
            "north,widget,90",
            "south,widget,5",
            "south,gadget,5",
            "east,gizmo,0",
            "east,widget,0");

    public static void main(String[] args) {
        Map<String, String> top;
        try {
            top = RevenueLeaderboard.topProductByRegion(SALES);
        } catch (RuntimeException e) {
            top = null;
            System.out.println("FAIL  topProductByRegion threw " + e.getClass().getSimpleName());
            failures++;
        }
        check("north best product", "widget", top == null ? null : top.get("north"));
        check("south tie broken alphabetically", "gadget", top == null ? null : top.get("south"));
        check("all-zero region still reports", "gizmo", top == null ? null : top.get("east"));
        check("region count", 3, top == null ? -1 : top.size());
        check("map is sorted by region", "{east=gizmo, north=widget, south=gadget}", String.valueOf(top));
        check("unknown region", null, top == null ? null : top.get("west"));

        Object ranked;
        try {
            ranked = String.valueOf(RevenueLeaderboard.rankedProducts(SALES));
        } catch (RuntimeException e) {
            ranked = "threw " + e.getClass().getSimpleName();
            failures++;
        }
        check("ranked products", "[widget=215, gizmo=200, gadget=5]", ranked);

        List<String> tied = Arrays.asList("a,zebra,10", "a,ant,10", "b,moose,10");
        check("full three-way tie sorts by name",
                "[ant=10, moose=10, zebra=10]",
                String.valueOf(RevenueLeaderboard.rankedProducts(tied)));

        check("empty sales, empty map", 0,
                RevenueLeaderboard.topProductByRegion(Collections.<String>emptyList()).size());
        check("empty sales, empty ranking", "[]",
                String.valueOf(RevenueLeaderboard.rankedProducts(Collections.<String>emptyList())));
        check("single line region", "solo",
                RevenueLeaderboard.topProductByRegion(Arrays.asList("only,solo,7")).get("only"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

