import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class RevenueLeaderboard {

    public static Map<String, String> topProductByRegion(List<String> sales) {
        Map<String, Map<String, Long>> totals = sales.stream()
                .map(line -> line.split(","))
                .collect(Collectors.groupingBy(
                        parts -> parts[0],
                        TreeMap::new,
                        Collectors.groupingBy(
                                parts -> parts[1],
                                Collectors.summingLong(parts -> Long.parseLong(parts[2])))));

        Map<String, String> best = new TreeMap<>();
        for (Map.Entry<String, Map<String, Long>> region : totals.entrySet()) {
            String winner = region.getValue().entrySet().stream()
                    .sorted(Map.Entry.<String, Long>comparingByValue(Comparator.reverseOrder())
                            .thenComparing(Map.Entry.comparingByKey()))
                    .map(Map.Entry::getKey)
                    .findFirst()
                    .orElse(null);
            best.put(region.getKey(), winner);
        }
        return best;
    }

    public static List<String> rankedProducts(List<String> sales) {
        Map<String, Long> totals = sales.stream()
                .map(line -> line.split(","))
                .collect(Collectors.groupingBy(
                        parts -> parts[1],
                        Collectors.summingLong(parts -> Long.parseLong(parts[2]))));

        return totals.entrySet().stream()
                .sorted(Map.Entry.<String, Long>comparingByValue(Comparator.reverseOrder())
                        .thenComparing(Map.Entry.comparingByKey()))
                .map(entry -> entry.getKey() + "=" + entry.getValue())
                .collect(Collectors.toList());
    }
}
